SELECT purchaseContract.primary_key as contractCode, purchaseContract.source, purchaseContract.contract_name, purchaseContract.contract_number, purchaseContract.contract_type, purchaseContract.buyer, purchaseContract.seller, purchaseContract.seller_name, purchaseContract.vender_data_code, purchaseContract.enterprise_code as ownedEnterpriseCode, purchaseContract.user_code, purchaseContract.user_name, purchaseContract.language, purchaseContract.payment_strategy, purchaseContract.column_titles, purchaseContract.amount_title, purchaseContract.product_detail, purchaseContract.state, purchaseContract.contract_time, purchaseContract.data_version, purchaseContract.sell_contract, purchaseContract.sell_quotation, purchaseContract.buyer_quotation, purchaseContract.signed_contract, purchaseContract.cancel_reason, purchaseContract.purchase_enquiry, purchaseContract.son_enterprise_code, purchaseContract.money_apply_returned, purchaseContract.invoice_apply_returned, purchaseContract.delete_flag, purchaseContract.business_belong, purchaseContract.qrcode_generated_flag, purchaseContract.has_receiving_details, purchaseContract.sign_addr, purchaseContract.contract_receiving_state, COALESCE(purchaseContract.ai_enable, FALSE) AS ai_enable FROM ${purchaseContractTableName} purchaseContract LEFT JOIN (SELECT DISTINCT signed_contract FROM ${contractPaymentRecordTableName} WHERE approval_status = 'CONFIRMED' AND delete_flag = 'f') moneyRecord ON purchaseContract.signed_contract = moneyRecord.signed_contract LEFT JOIN (SELECT DISTINCT signed_contract FROM ${contractInvoiceRecordTableName} WHERE approval_status = 'CONFIRMED' AND delete_flag = 'f') invoiceRecord ON purchaseContract.signed_contract = invoiceRecord.signed_contract WHERE purchaseContract.enterprise_code = #{enterpriseCode} AND purchaseContract.delete_flag = 'f'
AND purchaseContract.user_code IN
#{userCode}
AND purchaseContract.contract_number LIKE '%'|| #{contractNumber}||'%'
AND purchaseContract.seller_name LIKE '%'|| #{sellerName} ||'%'
AND purchaseContract.contract_time >= #{contractTimePreDate}
AND purchaseContract.contract_time <= #{contractTimePostDate}
AND purchaseContract.business_belong = #{businessBelong}
${dataScopeParams.dataScope}
AND moneyRecord.signed_contract IS NOT NULL
AND moneyRecord.signed_contract IS NULL
AND invoiceRecord.signed_contract IS NOT NULL
AND invoiceRecord.signed_contract IS NULL
AND purchaseContract.state = 'CANCELED'
AND purchaseContract.state != 'CANCELED'
ORDER BY COALESCE(purchaseContract.money_apply_returned, false) DESC, COALESCE(purchaseContract.invoice_apply_returned, false) DESC, purchaseContract.create_time DESC

